def tool_search(query):
    db = {"python": "Python is a high-level programming language.",
          "rag": "RAG stands for Retrieval-Augmented Generation.",
          "agent": "An agent uses an LLM to take autonomous actions."}
    q = query.lower()
    return next((v for k, v in db.items() if k in q), "No result found.")

def tool_calculate(expr):
    try:
        allowed = {c for c in "0123456789+-*/(). "}
        if all(c in allowed for c in expr):
            return str(eval(expr))
        return "Invalid expression"
    except Exception as e:
        return f"Error: {e}"

TOOLS = {"search": tool_search, "calculate": tool_calculate}

plan = [("search", "what is rag"), ("calculate", "2 ** 10"), ("search", "agent definition")]
print("Agent execution trace:")
for tool_name, args in plan:
    result = TOOLS[tool_name](args)
    print(f"  [{tool_name}({args!r})] -> {result}")
